import java.util.*;
import java.util.concurrent.atomic.*;

class Shop {
    private int rest;
    private long revenue;
    private final int price;

    Shop(int rest, int price) {
        this.rest = rest;
        this.price = price;
    }

    synchronized boolean buy(int amount) {
        if (rest < amount) return false;
        rest -= amount;
        revenue += (long) amount * price;
        return true;
    }

    synchronized int rest() {
        return rest;
    }

    synchronized long revenue() {
        return revenue;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner s = new Scanner(System.in);
        int stock = s.nextInt(), price = s.nextInt(), n = s.nextInt(), amount = s.nextInt();
        Shop shop = new Shop(stock, price);
        AtomicInteger ok = new AtomicInteger();
        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Thread t = new Thread(() -> {
                if (shop.buy(amount)) ok.incrementAndGet();
            });
            threads.add(t);
            t.start();
        }
        for (Thread t : threads) t.join();
        int sold = stock - shop.rest();
        System.out.println("ok=" + ok.get() + " sold=" + sold + " revenue=" + shop.revenue() + " rest=" + shop.rest());
        System.out.println((long) sold * price == shop.revenue() && sold == stock - shop.rest() ? "INVARIANT_OK" : "INVARIANT_BROKEN");
    }
}

