import java.util.*;

class Account {
    final int id;
    private long balance;

    Account(int id, long balance) {
        this.id = id;
        this.balance = balance;
    }

    void add(long amount) {
        balance += amount;
    }

    long balance() {
        return balance;
    }
}

public class Main {
    static void transfer(Account from, Account to, long amount) {
        Account first = from.id < to.id ? from : to, second = from.id < to.id ? to : from;
        synchronized (first) {
            synchronized (second) {
                from.add(- amount);
                to.add(amount);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        Scanner s = new Scanner(System.in);
        int m = s.nextInt();
        List<Account> accounts = new ArrayList<>();
        for (int i = 0; i < m; i++) accounts.add(new Account(i, s.nextLong()));
        int n = s.nextInt();
        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Account from = accounts.get(s.nextInt()), to = accounts.get(s.nextInt());
            long amount = s.nextLong();
            Thread t = new Thread(() -> transfer(from, to, amount));
            threads.add(t);
            t.start();
        }
        for (Thread t : threads) t.join();
        long total = 0;
        for (Account a : accounts) {
            System.out.println(a.id + "=" + a.balance());
            total += a.balance();
        }
        System.out.println("total=" + total);
    }
}
